    // assert math.ulp(maximum) == spacing  # tpyc: ok
    if (!((::tpy::stdlib::math::ulp(maximum) == spacing))) ::tpy::raise_assertion_error();
    // assert math.ulp(-maximum) == spacing  # tpyc: ok
    if (!((::tpy::stdlib::math::ulp(-(maximum)) == spacing))) ::tpy::raise_assertion_error();
    // assert math.ulp(predecessor) == spacing  # tpyc: ok
    if (!((::tpy::stdlib::math::ulp(predecessor) == spacing))) ::tpy::raise_assertion_error();
    // assert math.ulp(0.0) == 5e-324  # tpyc: ok
    if (!((::tpy::stdlib::math::ulp(0.0) == 5e-324))) ::tpy::raise_assertion_error();
    // assert math.ulp(-0.0) == 5e-324  # tpyc: ok
    if (!((::tpy::stdlib::math::ulp(-(0.0)) == 5e-324))) ::tpy::raise_assertion_error();
